<?php require __DIR__ . '/header.php'; if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); db()->prepare('UPDATE products SET price=?,stock=?,active=? WHERE id=?')->execute([(float)$_POST['price'],(int)$_POST['stock'],isset($_POST['active'])?1:0,(int)$_POST['id']]); } ?><div class="dashboard-title"><div><p class="eyebrow"><?= text('inventory') ?></p><h2><?= text('inventory') ?></h2></div></div><section class="admin-section"><?php foreach(db()->query('SELECT * FROM products ORDER BY id DESC') as $product): ?><form class="line admin-product" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="id" value="<?= $product['id'] ?>"><div class="art" style="background:<?= e($product['image_color']) ?>"><strong><?= e($product['short_name']) ?></strong></div><div><b><?= e($product['name']) ?></b><span>Stock <input name="stock" type="number" min="0" value="<?= $product['stock'] ?>"> Price <input name="price" type="number" min="0" value="<?= $product['price'] ?>"></span></div><label>Active <input name="active" type="checkbox" <?= $product['active']?'checked':'' ?>></label><button class="dark"><?= text('save') ?></button></form><?php endforeach; ?></section><?php require __DIR__ . '/footer.php'; ?>
